from flask import Flask, request
from flask_sqlalchemy import SQLAlchemy
import os

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = os.environ['DB_URL']
db = SQLAlchemy(app)

class Employee(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(50), nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)

    def __repr__(self):
        return '<Employee %r>' % self.name

@app.route('/')
def index():
    return '<h1>Employee List</h1>'

@app.route('/employee', methods=['POST'])
def employee():
    data = request.get_json()
    email = data.get('email')
    if email:
        employee = Employee(name=data.get('name'), email=email)
        db.session.add(employee)
        db.session.commit()
        return '<h1>Employee Created</h1>', 201
    else:
        return '<h1>Email Not Found</h1>', 404

@app.route('/employee/<email>')
def employee_detail(email):
    employee = Employee.query.filter_by(email=email).first()
    if employee:
        return f'<h1>{employee.name}</h1><p>Email: {email}</p><p>Address: {employee.email}</p>'
    else:
        return '<h1>Email Not Found</h1>', 404

if __name__ == '__main__':
    app.run(debug=True)
