Write a Python script that checks if a given password is strong or not. A strong password must have at least 8 characters, including at least one uppercase letter, one lowercase letter, one digit, and one special character. Use the `random` module to generate random characters for the password.

Solution:
import random
import string

def is_strong_password(password):
    if len(password) < 8:
        return False
    if not any(c.isupper() for c in password):
        return False
    if not any(c.islower() for c in password):
        return False
    if not any(c.isdigit() for c in password):
        return False
    if not any(c in string.punctuation for c in password):
        return False
    return True

def generate_password(length):
    chars = string.ascii_letters + string.digits + string.punctuation
    return ''.join(random.choice(chars) for _ in range(length))

# Test the function
print(is_strong_password('mypassword')) # False
print(is_strong_password(generate_password(8))) # True

